using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Threading;using System.Windows.Forms;using Frociart;
internal static class FileRuntimeUiTests {
 const BindingFlags Flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static int checks;static string root;
 static T Field<T>(object o,string name){return (T)o.GetType().GetField(name,Flags).GetValue(o);}
 static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,Flags).Invoke(o,args);}
 static void Check(bool value,string message){if(!value)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
 static void Pump(int ms=120){var end=DateTime.UtcNow.AddMilliseconds(ms);do{Application.DoEvents();Thread.Sleep(2);}while(DateTime.UtcNow<end);}
 static void Until(Func<bool> complete,string reason){var limit=DateTime.UtcNow.AddSeconds(8);while(!complete()&&DateTime.UtcNow<limit)Pump(15);Check(complete(),reason);}
 static void Load(MainForm f,string code){f.SetDocument(FlowPseudocode.Decode(code),null,false);f.Runner=new Interpreter(f.Project);Field<SidebarTabs>(f,"tabs").SelectedTab=Field<Panel>(f,"runTab");Call(f,"RefreshRuntime");Pump();}
 static void WaitFile(MainForm f){for(int i=0;i<100&&f.Runner.State!=RuntimeState.WaitingForFile&&f.Runner.State!=RuntimeState.Error;i++)f.Runner.Step();Check(f.Runner.State==RuntimeState.WaitingForFile,"Program awaits native file action");Call(f,"RefreshRuntime");Pump();}
 static void Finish(MainForm f){for(int i=0;i<100&&f.Runner.State!=RuntimeState.Completed&&f.Runner.State!=RuntimeState.Error;i++)f.Runner.Step();Check(f.Runner.State==RuntimeState.Completed,"Program finishes after file grant");}
 static System.Collections.Generic.IEnumerable<Control> Desc(Control root){foreach(Control c in root.Controls){yield return c;foreach(var n in Desc(c))yield return n;}}
 static void Capture(Form form,string name){using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(root,name+".png"));}}
 static void RecoveryDialog(MainForm main,FlowFileRecovery.Entry entry){
  Exception error=null;bool done=false,clicked=false;int ticks=0;var timer=new System.Windows.Forms.Timer{Interval=60};
  timer.Tick+=delegate{try{var form=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f.Text=="File generato — Frociart");if(form==null){if(++ticks>100)throw new Exception("Recovery form never appeared");return;}form.Location=new Point(-3000,-3000);
    if(!clicked){clicked=true;form.Size=new Size(470,420);form.PerformLayout();var preview=Desc(form).OfType<TextBox>().Single(t=>t.AccessibleName=="Anteprima del file generato");Check(preview.ReadOnly&&preview.Text=="recover me\n","Recovery opens real preserved text");var save=Desc(form).OfType<FlowButton>().Single(b=>b.Text=="Salva una copia");var row=save.Parent;foreach(Control b in row.Controls)Check(b.Left>=0&&b.Right<=row.ClientSize.Width,"Recovery actions fit narrow window");save.PerformClick();return;}
    if(Desc(form).OfType<Label>().Any(l=>l.Text.StartsWith("Copia salvata"))){Check(File.ReadAllText(Path.Combine(root,"recovered.txt"))=="recover me\n","Recovery saves actual UTF-8 file");Check(main.FileRecovery.List().Any(e=>e.Id==entry.Id),"Save copy keeps recovery draft");Capture(form,"recovery-narrow");timer.Stop();form.Close();done=true;}
    else if(++ticks>100)throw new Exception("Recovery save never completed");
   }catch(Exception ex){error=ex;timer.Stop();foreach(var f in Application.OpenForms.Cast<Form>().Where(f=>f!=main).ToArray())f.Close();done=true;}};
  timer.Start();Call(main,"ShowGeneratedFile",entry);Until(()=>done,"Recovery dialog completes");timer.Dispose();if(error!=null)throw error;
 }
 [STAThread]static int Main(){try{
  root=Path.Combine(Environment.GetEnvironmentVariable("RECOVERY_TEST_ROOT")??Path.GetTempPath(),"pc-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Environment.SetEnvironmentVariable("FROCIART_DATA_DIR",Path.Combine(root,"data"));Application.EnableVisualStyles();
  Exception failure=null;using(var f=new MainForm(null,true)){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-3000,-3000);f.Shown+=delegate{f.BeginInvoke(new Action(delegate{try{Pump();f.EnterEditor();
   Load(f,"APRI_FILE LETTURA \"input.txt\"\nLEGGI_FILE x\nSTAMPA x");WaitFile(f);var action=Field<FlowButton>(f,"runtimeFileAction");Check(action.Visible&&action.Enabled&&action.Text.Contains("leggere"),"Read wait exposes enabled native action");Check(!Field<FlowButton>(f,"runtimePlay").Enabled,"Play is disabled while waiting for file");Capture(f,"read-wait");var request=f.Runner.PendingFile;int steps=f.Runner.Steps;
   f.RuntimeFilePicker=(read,name)=>null;action.PerformClick();Check(f.Runner.PendingFile==request&&f.Runner.Steps==steps&&action.Enabled,"Picker cancel retains exact request without stepping");
   f.RuntimeFilePicker=(read,name)=>{throw new IOException("picker unavailable");};action.PerformClick();Check(f.Runner.PendingFile==request&&action.Enabled,"Picker failure remains retryable");
   string input=Path.Combine(root,"input.txt");File.WriteAllText(input,"23");f.RuntimeFilePicker=(read,name)=>input;f.RuntimeFileRead=path=>{throw new IOException("unreadable");};action.PerformClick();Until(()=>!Field<bool>(f,"fileIoBusy"),"Read failure returns from busy state");Check(f.Runner.PendingFile==request&&!f.Runner.Files.HasRead,"Failed read cannot acknowledge request");
   f.RuntimeFileRead=FlowFileStorage.Read;action.PerformClick();Until(()=>!Field<bool>(f,"fileIoBusy")&&f.Runner.PendingFile!=request,"Actual read is accepted");Until(()=>!action.Visible,"File control hides after successful read");Check(f.Runner.Files.HasRead,"Actual chosen text opens input channel");Finish(f);Check(String.Join("|",f.Runner.Output)=="23","Chosen file supplies interpreter input");
   Load(f,"APRI_FILE SCRITTURA \"result.txt\"\nSCRIVI_FILE \"recover me\"");WaitFile(f);request=f.Runner.PendingFile;Check(action.Text.Contains("Salva"),"Write wait exposes save action");var entry=f.FileRecovery.List().Single();Check(f.FileRecovery.Load(entry).Text=="recover me\n","Generated output is durable before picker opens");
   f.RuntimeFilePicker=(read,name)=>Path.Combine(root,"result.txt");f.RuntimeFileSave=(path,text)=>{throw new IOException("disk failure");};action.PerformClick();Until(()=>!Field<bool>(f,"fileIoBusy"),"Save failure returns from busy state");Check(f.Runner.PendingFile==request&&f.Runner.Files.OutputDraft=="recover me\n"&&f.FileRecovery.List().Count==1,"Save failure preserves pending request and draft");
   Field<FlowButton>(f,"resetButton").PerformClick();Check(f.Runner==null,"Native reset replaces execution");Check(f.FileRecovery.Load(entry).Text=="recover me\n","Native reset preserves generated file");f.RuntimeFileSave=FlowFileStorage.Save;f.RuntimeFilePicker=(read,name)=>Path.Combine(root,"recovered.txt");RecoveryDialog(f,entry);
   Load(f,"APRI_FILE SCRITTURA \"written.txt\"\nSCRIVI_FILE 9");WaitFile(f);request=f.Runner.PendingFile;entry=f.FileRecovery.List().Single(e=>e.Name=="written.txt");f.RuntimeFilePicker=(read,name)=>Path.Combine(root,"written.txt");action.PerformClick();Until(()=>f.Runner.PendingFile!=request,"Save acknowledges after actual stream completion");Check(File.ReadAllText(Path.Combine(root,"written.txt"))=="9\n","Native save writes exact result");Check(!f.FileRecovery.List().Any(e=>e.Id==entry.Id),"Confirmed save removes only its own draft");Finish(f);
   Load(f,"APRI_FILE LETTURA \"old.txt\"\nLEGGI_FILE x");WaitFile(f);var old=f.Runner;var entered=new ManualResetEventSlim();var release=new ManualResetEventSlim();var returned=new ManualResetEventSlim();f.RuntimeFileRead=path=>{entered.Set();release.Wait(5000);returned.Set();return "99";};int picks=0;f.RuntimeFilePicker=(read,name)=>{picks++;return input;};f.ChooseRuntimeFile();Until(()=>entered.IsSet,"Delayed read started");f.ChooseRuntimeFile();Check(picks==1,"Duplicate action does not start another picker");Load(f,"x=7\nSTAMPA x");var next=f.Runner;release.Set();Until(()=>returned.IsSet,"Old read is released");Pump(180);Check(f.Runner==next&&!next.Files.HasRead&&next.Steps==0,"Late read cannot change replacement execution");Check(old.State==RuntimeState.WaitingForFile,"Stale result does not advance old runner");entered.Dispose();release.Dispose();returned.Dispose();f.RuntimeFileRead=FlowFileStorage.Read;
   Load(f,"FUNZIONE apri()\nAPRI_FILE LETTURA \"input.txt\"\nFINE FUNZIONE\nCHIAMA apri()\nLEGGI_FILE x\nSTAMPA x");f.DebugStep(FlowDebugger.Command.Into);f.DebugStep(FlowDebugger.Command.Over);Until(()=>f.Runner.State==RuntimeState.WaitingForFile&&action.Visible&&action.Enabled,"Step over pauses inside function for file");var debugger=(FlowDebugger)Call(f,"GetDebugger");f.StartRun();f.DebugStep(FlowDebugger.Command.Into);Check(debugger.Mode==FlowDebugger.Command.Over&&debugger.Active,"Keyboard actions during file wait preserve step-over plan");f.RuntimeFilePicker=(read,name)=>input;action.PerformClick();Until(()=>f.Runner.State!=RuntimeState.WaitingForFile&&!Field<bool>(f,"fileIoBusy"),"Step-over picker read finishes");Until(()=>!debugger.Active,"Step over resumes after picker and returns to caller");Check(f.Runner.CallDepth==1&&f.Runner.Output.Count==0&&!f.Runner.Variables.ContainsKey("x"),"Step over stops before the caller's next read");
   }catch(Exception ex){failure=ex;}finally{f.Runner=null;f.Close();}}));};Application.Run(f);
  }if(failure!=null)throw failure;Console.WriteLine("FileRuntimeUiTests PASS "+checks+" assertions; captures="+root);return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
